/**
 * Strip soft hyphens / zero-width chars WhatsApp clients sometimes inject into long URLs.
 * Ensures an http(s):// scheme so WhatsApp can auto-link.
 */
function sanitizeFormLink(url) {
  let s = String(url || '')
    .replace(/[\u00AD\u200B-\u200D\uFEFF]/g, '')
    .replace(/^<|>$/g, '')
    .trim();
  if (!s) return '';
  if (!/^https?:\/\//i.test(s)) {
    s = `http://${s}`;
  }
  return s.replace(/\/+$/, (m, offset, str) => {
    // keep trailing slash only if path is just "/"
    return str.replace(/^https?:\/\//i, '').includes('/') ? '' : m;
  }).replace(/(?<!:)\/+$/, '') || s;
}

/**
 * Format a URL so WhatsApp renders it as a tappable blue link.
 * Bare URL on its own + angle brackets (WA linkifies the http(s) token inside).
 */
function formatWhatsAppClickableLink(url) {
  const href = sanitizeFormLink(url);
  if (!href) return '';
  return `<${href}>`;
}

/**
 * Build a WhatsApp-safe form-link message.
 * Splits around {{form_link}} so the URL can be sent alone (avoids WhatsApp
 * soft-hyphenating long URLs mid-line). Prefer: intro → link → optional footer.
 * `link` is already wrapped for clickable rendering; `linkUrl` is the bare href.
 */
function buildFormLinkParts(template, vars = {}) {
  const linkUrl = sanitizeFormLink(vars.form_link);
  const link = formatWhatsAppClickableLink(linkUrl);
  const marker = '___FORM_LINK___';
  const rendered = renderTemplate(String(template || ''), {
    ...vars,
    form_link: marker,
  }).replace(/[\u00AD\u200B-\u200D\uFEFF]/g, '');

  const idx = rendered.indexOf(marker);
  let intro;
  let footer = '';

  if (idx === -1) {
    intro = rendered.replace(/\n{3,}/g, '\n\n').trim() || 'Please fill out this short form:';
  } else {
    intro = rendered
      .slice(0, idx)
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
    footer = rendered
      .slice(idx + marker.length)
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
    if (!intro) intro = 'Please fill out this short form:';
  }

  const combined = [intro, link, footer].filter(Boolean).join('\n\n');
  return { intro, link, linkUrl, footer, combined };
}

/**
 * Single-string version when a caller cannot send two messages.
 */
function formatFormLinkMessage(template, vars = {}) {
  return buildFormLinkParts(template, vars).combined;
}

module.exports = {
  parseExtra,
  formatExtraDetails,
  buildLeadVars,
  renderTemplate,
  buildConfirmationMessage,
  buildForwardMessage,
  sanitizeFormLink,
  formatWhatsAppClickableLink,
  buildFormLinkParts,
  formatFormLinkMessage,
  DEFAULT_CONFIRMATION_TEMPLATE,
  DEFAULT_FORWARD_TEMPLATE,
};

